import { DEFAULTS } from '../config/defaults.js';

export function requestOptions(env = process.env) {
  const n = Number(env.REQUEST_TIMEOUT_MS);
  const timeoutMs = Number.isInteger(n) && n > 0 ? n : DEFAULTS.timeoutMs;
  return { retries: DEFAULTS.retries, timeoutMs };
}

reference.test/client.test.js:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { requestOptions } from '../src/index.js';
test('defaults', () => assert.deepEqual(requestOptions({}), { retries: 2, timeoutMs: 1000 }));
test('env override', () => assert.equal(requestOptions({ REQUEST_TIMEOUT_MS: '250' }).timeoutMs, 250));
test('invalid values fall back', () => assert.equal(requestOptions({ REQUEST_TIMEOUT_MS: 'abc' }).timeoutMs, 1000));

