const run = (value) => spawnSync(process.execPath, ['--input-type=module', '-e', "import('./src/index.js').then((m) => console.log(m.requestOptions().timeoutMs))"], { env: { ...process.env, ...(value === undefined ? {} : { REQUEST_TIMEOUT_MS: value }) }, encoding: 'utf8' }).stdout.trim();
assert.equal(run(undefined), '1000');
assert.equal(run('250'), '250');
assert.equal(run('nope'), '1000');
